import java.util.ArrayList;
import java.util.List;

/**
 * 简单的学生管理器，功能不完整。
 * 用于测试 NaturalCC 代码补全和修复。
 */
public class StudentManager {
    private List<Student> students;

    /**
     * 构造一个空的学生管理器。
     */
    public StudentManager() {
        this.students = new ArrayList<>();
    }

    /**
     * 添加一个具有给定姓名和年龄的学生。
     *
     * @param name 学生姓名（不能为 null）
     * @param age  学生年龄（必须为正数）
     * @return 如果学生添加成功返回 true，否则返回 false
     */
    // TODO: 完成此方法 - 应添加学生并在成功时返回 true
    public boolean addStudent(String name, int age) {
        if (name == null || age <= 0) {
            return false;
        }
        students.add(new Student(name, age));
        return true;
    }

    /**
     * 根据姓名查找学生。
     *
     * @param name 要搜索的姓名
     * @return 具有给定姓名的 Student 对象，如果未找到则返回 null
     */
    // TODO: 完成此方法 - 应根据姓名查找学生
    public Student findStudent(String name) {
        for (Student s : students) {
            if (s.getName().equals(name)) {
                return s;
            }
        }
        return null;
    }

    /**
     * 计算所有学生的平均年龄。
     *
     * @return 平均年龄，如果没有学生则返回 0.0
     */
    // BUG: 计算平均值前应检查列表是否为空
    public double calculateAverageAge() {
        if (students.isEmpty()) {
            return 0.0;
        }
        int total = 0;
        for (Student s : students) {
            total += s.getAge();
        }
        return (double) total / students.size();
    }

    /**
     * 移除第一个具有给定姓名的学生。
     *
     * @param name 要移除的学生姓名
     */
    // BUG: 未检查重复姓名
    public void removeStudent(String name) {
        for (int i = 0; i < students.size(); i++) {
            if (students.get(i).getName().equals(name)) {
                students.remove(i);
                break;
            }
        }
    }

    /**
     * 返回当前管理的学生数量。
     *
     * @return 学生数量
     */
    public int getStudentCount() {
        return students.size();
    }

    /**
     * 表示一个具有姓名和年龄的学生。
     */
    public static class Student {
        private String name;
        private int age;

        /**
         * Constructs a Student with the given name and age.
         *
         * @param name the student's name
         * @param age  the student's age
         */
        public Student(String name, int age) {
            this.name = name;
            this.age = age;
        }

        /**
         * Returns the student's name.
         *
         * @return the name
         */
        public String getName() { return name; }

        /**
         * Returns the student's age.
         *
         * @return the age
         */
        public int getAge() { return age; }

        /**
         * Sets the student's name.
         *
         * @param name the new name
         */
        public void setName(String name) { this.name = name; }

        /**
         * Sets the student's age.
         *
         * @param age the new age
         */
        public void setAge(int age) { this.age = age; }

        @Override
        public String toString() {
            return "Student{name='" + name + "', age=" + age + "}";
        }
    }

    /**
     * Main method for demonstration.
     *
     * @param args command-line arguments (not used)
     */
    public static void main(String[] args) {
        StudentManager manager = new StudentManager();
        manager.addStudent("Alice", 20);
        manager.addStudent("Bob", 22);
        System.out.println("Total students: " + manager.getStudentCount());
        System.out.println("Average age: " + manager.calculateAverageAge());
    }
}
